return [
  { json: { project_id: '691331356a3b9a68428ab3.43540470', project_name: 'Chat AI - frontend' } },
  { json: { project_id: '225008626a33e62b328c63.04676982', project_name: 'Chat AI (emails)' } }
];

const meta = $('Projects').all();
const rows = $input.all();
const out = [];
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  const r = rows[i].json || {};
  if (r.statusCode !== 200) { continue; }
  for (const s of ((r.body && r.body.screenshots) || [])) {
    const desc = String(s.description || '');
    if (desc.indexOf('figma.com') === -1) { continue; }
    let clean = desc.replace(/\s*[\u2014-]\s*https?:\/\/\S+/g, '');
    clean = clean.replace(/https?:\/\/\S+/g, '');
    clean = clean.replace(/^\s*Figma\s*\u00b7\s*/i, '');
    clean = clean.replace(/\s{2,}/g, ' ').replace(/[\s\u00b7\u2014-]+$/, '').trim();
    if (!clean) { clean = String(s.title || 'Design screen'); }
    out.push({ json: {
      project_id: m.project_id,
      project_name: m.project_name,
      screenshot_id: s.screenshot_id,
      title: s.title || '',
      before: desc,
      after: clean,
      key_ids: s.key_ids || []
    } });
  }
}
return out;

const meta = $('Plan Rewrites').all();
const rows = $input.all();
let ok = 0;
const bad = [];
const samples = [];
let keysKept = 0;
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  const r = rows[i].json || {};
  if (r.statusCode === 200) {
    ok++;
    keysKept += (m.key_ids || []).length;
    if (samples.length < 4) { samples.push({ title: m.title, before: m.before, after: m.after, keys: (m.key_ids || []).length }); }
  } else {
    bad.push(m.title + ' -> ' + r.statusCode + ' ' + JSON.stringify(r.body).slice(0, 160));
  }
}
return [{ json: { rewritten: ok, failed: bad.length, failures: bad, key_links_preserved: keysKept, samples: samples } }];
